from build_engine3 import *
cover=[
step('entry','Confirm right-cover access','Start with a supported removed engine, oil and coolant drained, clutch cover removed, and hoses/hardware clear of the right cover. Preserve the installed water pump until its separate bench operation is selected.',[251,300],'Drained engine and clutch-cover access confirmed.',False,True),
step('remove','Remove the right cover','Remove oil-filter-element cover and element, then filler cap. Map the right-cover bolt lengths/locations from the diagram, remove the bolts and lift away the case cover. Retain the two dowels, discard the gasket, and keep the cover sealing parts identified.',[251],'Cover, element, filler and two dowels retained.',False,True),
step('service','Record any cover service needed','Inspect the removed cover and its sealing parts. The separate water-pump operation begins with this cover on the bench. If renewing the illustrated internal oil seal, remove its circlip/old seal and retain the check-ball seat at its shown position; replace the seal and circlip.',[251,257,300],'Cover service performed or not needed recorded.',True,True),
step('seal','Install the cover oil seal if renewed','For a renewed internal seal, grease its lip with lithium-soap grease and press it parallel at0mm depth with its manufacturer marks/numbers facing inward. Install the new circlip and restore the illustrated check-ball seat. If untouched, record that the original arrangement remains installed.',[251,257],'Seal0mm/inward marks and new clip recorded, or intact original arrangement.',True,True),
step('case-close','Refit the right cover','After required primary/oil-pump/shift work is complete, fit both dowels and a new right-cover gasket. Seat the cover and tighten its bolts progressively in a crisscross pattern to10Nm at their original locations. Do not use bolts to pull a binding pump drive into place.',[257,258],'Two dowels, new gasket and10Nm cover bolts verified.',True,True),
step('filter','Restore oil filter and filler','Install the exact filter element in its original direction and its cover with a new O-ring lubricated with lithium-soap grease; tighten cover bolts10Nm. Fit filler cap with its new O-ring lubricated with lithium-soap grease. Oil filling and level checks belong to final engine commissioning.',[251],'Filter direction, new O-rings and10Nm cover closure recorded.',True,True)]
procedure('right-cover-bench-v1','Remove and reseal the right engine cover',cover,['Engine out, fluids drained, clutch cover removed, external hoses clear.'],['Right cover/filter/filler sealed; clutch cover and fluid commissioning remain.'],['Torque wrench accurate at10Nm','Parallel seal driver and circlip tools'],['New right-cover gasket','New filter-cover and filler-cap O-rings','New internal oil seal/circlip if renewed','Lithium-soap grease'],['Clutch basket installation','Water-pump rebuild is separate','Final oil fill and engine commissioning'],['engine','crankcase'])

water=[
step('entry','Confirm water-pump bench access','Oil and coolant are drained and the right crankcase cover is removed. Support the cover so pump-shaft and seal removal cannot damage its mating face. This guide renews bearings/seal and retains the intact impeller-shaft assembly unless that assembly is defective.',[300,301],'Removed right cover and drained state confirmed.',False,True),
step('open','Remove pump cover and shaft assembly','Remove pump-cover bolts and coolant-drain bolt/washer. Lift cover and remove its O-ring and two dowels. Remove the rear shaft circlip and withdraw the complete impeller-shaft assembly. Remove the pump housing and its O-ring. Keep the two impellers and shaft assembled together for this route.',[300,301],'Cover, two dowels, housing and intact shaft assembly accounted for.',False,True),
step('inspect','Inspect the removed pump','Inspect cover, housing, impeller shaft and both impellers for cracks, damage or wear; replace defective parts with exact stock components. Rotate bearing inner races by finger; roughness or seizure requires replacement. Unusual coolant loss/discoloration or milky engine oil calls for oil-seal removal; a removed seal cannot be reused.',[301,302],'Pump-part condition and bearing observations saved.',True,True),
step('bearings-out','Remove the old bearings and seal','Remove the old oil seal and the two bearings from the supported right cover. Discard the removed bearings and seal. Protect the bores and mating surface; use the press and bearing-driver operation described for the engine bearings rather than hammering the cover.',[280,300,302],'Old bearings/seal removed; bores intact.',False,True),
step('seal-install','Install the new pump seal','Apply lithium-soap grease to the new seal lip. Point its illustrated projections outward and install parallel to0mm indicated depth. Keep its spring in place and avoid cutting the lip.',[300,301,302],'Outward projections,0mm depth and intact spring/lip recorded.',True,True),
step('bearings-install','Install both new bearings','Oil the bearings and press them parallel by their outer races to the0mm indicated seated positions. Verify smooth inner-race movement after seating.',[300,301,302],'Two new bearings seated0mm and moving smoothly.',True,True),
step('shaft-install','Refit housing and intact impeller assembly','Grease the new housing O-ring with lithium-soap grease. Install it, the pump housing and the intact serviceable impeller-shaft assembly, protecting the seal lip and spring. Fit a new rear circlip fully into its groove.',[300,302],'New housing O-ring and rear clip installed; shaft/impellers serviceable.',False,True),
step('close','Close the pump','Fit both dowels and the new cover O-ring with lithium-soap grease. Refit the pump cover and tighten its bolts10Nm. Fit a new drain washer and tighten coolant-drain bolt10Nm. Final coolant fill/leak checks follow engine cover/engine installation.',[300,302,303],'New cover O-ring, two dowels, cover10Nm and drain10Nm saved.',True,True)]
procedure('water-pump-bench-v1','Renew water-pump bearings and seals',water,['Right crankcase cover removed; oil/coolant drained.','Impeller-shaft assembly retained intact; replace it as an exact assembly if defective.'],['Water pump closed on right cover with renewed bearings/seals; right-cover installation and coolant commissioning remain.'],['Bearing press and parallel outer-race drivers','Seal driver, circlip tools and torque wrench accurate at10Nm'],['Two new pump bearings, new oil seal and rear shaft circlip','Two new housing/cover O-rings and coolant-drain washer','Exact intact impeller-shaft assembly if required','Engine oil and lithium-soap grease'],['Disassembly of impeller-shaft stack','Aftermarket pump conversion','Final coolant commissioning'],['engine','water_pump'])
manifest()
